Основная причина проблемы в том, что вы применяете **прямой** поворот камеры к относительной позиции, а для радара нужен **обратный** поворот, и только по оси Y (Yaw). Кроме того, полный кватернион камеры содержит Pitch и Roll, которые искажают 2D-проекцию радара при наклоне камеры.

Ниже исправленный вариант с подробными комментариями:

```cpp
void addPlayersToRadar(Player* player) 
{
    Vector3 myPos   = GetPosition(myPlayer);
    Vector3 targetPos = player->position;
    Vector3 delta   = targetPos - myPos;

    // 1. Получаем направление взгляда камеры и "сплющиваем" его на плоскость XZ (только YAW)
    Vector3 camForward = GetRotation(get_main()) * Vector3(0, 0, 1); // Forward зависит от движка
    camForward.y = 0.0f;
    float len = sqrtf(camForward.x * camForward.x + camForward.z * camForward.z);
    if (len > 0.001f) camForward /= len;

    // 2. Создаём кватернион YAW камеры и берём обратный (Inverse)
    // Обратный поворот заставляет точки вращаться "вместе" с камерой на радаре
    Quaternion camYaw   = Quaternion::LookRotation(camForward, Vector3(0, 1, 0));
    Quaternion invCamYaw = Quaternion::Inverse(camYaw);

    // 3. Применяем обратный YAW к относительной позиции
    Vector3 localPos = invCamYaw * delta;

    // 4. Круговое ограничение радиуса (вместо квадратного if x>=180 / z>=180)
    float dist2D = sqrtf(localPos.x * localPos.x + localPos.z * localPos.z);
    float maxRad = 180.0f;
    if (dist2D > maxRad) {
        float scale = maxRad / dist2D;
        localPos.x *= scale;
        localPos.z *= scale;
    }

    // 5. Преобразование в экранные координаты ImGui
    // В ImGui ось Y идёт ВНИЗ, поэтому "вперёд" по Z нужно инвертировать
    float radarX = radar_center.x + localPos.x;
    float radarY = radar_center.y - localPos.z; 

    bg->AddCircleFilled({radarX, radarY}, 5.0f, ImColor(255, 0, 0, 255));
}
